import test from 'node:test';import assert from 'node:assert/strict';
import {normalizeTech,techAction,techView,techRoute,techPredict,techProbes,techAvailableJobs,techArtKeys,techArt,techArtKey,techObjects,techDoors,techHQLinks} from '../src/hq-tech.js';
import {normalizeMachines,machineCommand,machineParts,machineName,machinePadAllows,machineView} from '../src/machines.js';import {objects,materials} from '../src/data.js';import {zones,zoneExit} from '../src/zones.js';import {pathfind,cellAt} from '../src/navigation.js';import {getJournalEntries} from '../src/journal.js';
const step=(s,type,value)=>techAction(s,{type,value}).tech;
function robots(){let m=normalizeMachines();for(const tool of ['gripper','sprayer','brush']){m=machineCommand(m,{type:'blueprint',value:'helperbot'}).machines;m=machineCommand(m,{type:'part',slot:'module',value:tool}).machines;m=machineCommand(m,{type:'helper'}).machines;m=machineCommand(m,{type:'save'}).machines;}return m.models.map(m=>({...m,name:machineName(m),toolName:machineParts[m.parts.module].name}));}
test('HQ rooms, neighboring doors and all activities have reachable approaches and return paths',()=>{for(const o of [...techObjects,...techDoors,...techHQLinks]){const from=zones[o.zone].spawn,to=[o.x-65,o.y+55];assert.ok(pathfind(from,to,o.zone).length||cellAt(...from,o.zone).join()===cellAt(...to,o.zone).join(),o.id);}assert.equal(zoneExit('grounds','coding'),'home');assert.equal(zoneExit('hq','robotics'),'hq-robotics');assert.equal(zoneExit('coding','robotics'),'coding-nextdoor');assert.equal(zoneExit('robotics','coding'),'robotics-nextdoor');assert.equal(zoneExit('robotics','farm'),'robotics-exit');});
test('binary, sequencing, branching and toy syntax respond to choices without timing or typing',()=>{let s=normalizeTech();for(const n of [8,4,2,1])s=step(s,'bit',n);assert.equal(s.bits,15);s=step(s,'bit',4);assert.equal(s.bits,11);assert.ok(techRoute(['right','right']).blocked);s=step(s,'sequence','example');assert.ok(techRoute(s.queue).delivered);s=step(s,'sequence','run');assert.ok(s.completed.includes('sequence'));s=step(s,'rule','run');assert.ok(s.dry&&s.thenWater&&s.ruleRan);s=step(s,'syntax','run');assert.ok(!s.completed.includes('syntax'));s=step(s,'syntax','example');s=step(s,'syntax','run');assert.ok(s.completed.includes('syntax'));assert.deepEqual(normalizeTech(JSON.parse(JSON.stringify(s))),s);assert.equal(normalizeTech(null).bits,0);});
test('the tiny model compares examples and visibly makes a checkable mistake rather than claiming real intelligence',()=>{assert.equal(techPredict([],techProbes[0]),'need-examples');assert.equal(techPredict(['plant'],techProbes[1]),'unsure');assert.equal(techPredict(['plant','machine'],techProbes[0]),'plant');assert.equal(techPredict(['plant','machine'],techProbes[1]),'machine');assert.equal(techPredict(['plant','machine'],techProbes[2]),'plant');let s=step(step(normalizeTech(),'teach','plant'),'teach','machine');s.probe=2;s=step(s,'ai','test');assert.match(techView(s,'ai').text,/can be wrong/);assert.match(techView(s,'ai-explain').text,/pretend/);});
test('robot jobs require an owned matching tool and a human plan, and rotor drones stay out of vacuum worlds',()=>{const ctx={robots:robots()},bot=ctx.robots[0];assert.deepEqual(techAvailableJobs(bot),['construction','tidy','recycle']);let s=techAction({}, {type:'robot',value:bot.id},ctx).tech;s=techAction(s,{type:'job',value:'tidy'},ctx).tech;assert.equal(techAction(s,{type:'job-run'},ctx).effect,null);s=techAction(s,{type:'job-plan',value:'box'},ctx).tech;const r=techAction(s,{type:'job-run'},ctx);assert.equal(r.effect,'tidy');assert.ok(r.tech.completed.includes('tidy'));assert.equal(techAction({...s,job:'fire'},{type:'job-run'},ctx).effect,null);assert.deepEqual(techAvailableJobs(ctx.robots[1]),['farm','fire']);assert.deepEqual(techAvailableJobs(ctx.robots[2]),['tidy','care']);assert.equal(machinePadAllows('drone','chapterMoon',1),false);assert.equal(machinePadAllows('drone','chapterEarth',1),true);assert.equal(machinePadAllows('helperbot','farm',0),true);s=normalizeTech();for(const x of ['reduce','ask','help'])s=step(s,'steward',x);assert.ok(s.completed.includes('steward'));});
test('all lessons fit six native controls including narration, have bounded text and stateful art, and journal actual actions',()=>{const ctx={robots:robots()},s=normalizeTech({bits:15,queue:['right','up'],sequenceRan:true,ruleRan:true,syntax:{word:true,open:true,close:true,ran:true},examples:['plant','machine'],aiRan:true,sensorRan:true,air:false,droneRan:true,robotId:'m1',job:'tidy',jobRan:true});const routes=['home','malik','mike','kaito','build','binary','sequence','sequence-tools','rule','syntax','syntax-help','ai','ai-explain','sensors','drone','jobs:0','robot-jobs','job','steward'];for(const route of routes){const v=techView(s,route,ctx);assert.ok(v.actions.length<=5,route);assert.ok(v.text.replace(/(.{1,43})(?:\s|$)/g,'$1\n').trim().split('\n').length<=7,route+': '+v.text);assert.ok(techArtKeys.includes(techArtKey(s,v.art)));}for(const key of techArtKeys)assert.match(techArt(key),/viewBox="0 0 320 180"/);const visited=new Set(['coding-binary']);assert.equal(getJournalEntries('experiments',new Set(),visited,objects,materials).length,0);s.completed=['binary','ai'];const entries=getJournalEntries('experiments',new Set(),visited,objects,materials,{},{},{},{},{},{},s);assert.equal(entries.length,2);assert.equal(entries[1].target,'coding-ai');assert.equal(getJournalEntries('did',new Set(),visited,objects,materials).length,1);});
